    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ?"
                + " ORDER BY from_date, id", ROW, sheetId);
        Map<Long, Map<Long, BigDecimal>> totals = new HashMap<>();
        Map<Long, Map<Long, BigDecimal>> carried = new HashMap<>();
        jdbc.query("SELECT t.period_id, t.person_id, t.total, t.carried FROM period_person_total t JOIN period p ON p.id = t.period_id"
                + " WHERE p.sheet_id = ?", rs -> {
                    totals.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                    BigDecimal personCarried = rs.getBigDecimal("carried");
                    if (personCarried != null) {
                        carried.computeIfAbsent(rs.getLong("period_id"), k -> new LinkedHashMap<>())
                                .put(rs.getLong("person_id"), personCarried);
                    }
                }, sheetId);
        return periods.stream().map(p -> withTotals(p, totals.getOrDefault(p.id(), Map.of()),
                carried.getOrDefault(p.id(), Map.of()))).toList();
    }

    private static Period withTotals(Period p, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        return new Period(p.id(), p.sheetId(), p.name(), p.from(), p.to(), p.closed(), p.closedTotal(), personTotals, p.soft(), p.cap(),
                personCarried, p.locked());
    }

